function result = runDiagnosticAirSurfaceISMWavefront(varargin)
%RUNDIAGNOSTICAIRSURFACEISMWAVEFRONT Fast non-correction air-surface fit.
%
%   This runner is for checking whether the water/glass/air forward model
%   reproduces the measured axial trace, detector intensities, and XY images.
%   It deliberately excludes coma and does not claim correction readiness.

    alignmentCsv = ['D:\Luminosa\Data\PSF_batch_outputs\ISM_Aberation2_73\' ...
        'xz_yz_plots\x0_4uW_0_19collar_80mmlens_20260515_155744_frame_alignment.csv'];
    root=fileparts(fileparts(mfilename('fullpath')));

    args={ ...
        'sampleGeometry','airOnGlass', ...
        'objectiveNA',1.2, ...
        'objectiveMagnification',60, ...
        'immersionRefractiveIndex',1.33, ...
        'glassRefractiveIndex',1.518, ...
        'sampleRefractiveIndex',1.0003, ...
        'coverslipThicknessUm',190, ...
        'designCoverslipThicknessUm',190, ...
        'beadBottomHeightUm',0, ...
        'fitModes',{'defocus','astig_x','astig_y','spherical'}, ...
        'maxIter',8, ...
        'airBeadAxialSamples',3, ...
        'runProfiles',false, ...
        'runSignProfiles',false, ...
        'nBootstrap',0, ...
        'requireValidationPrerequisites',false, ...
        'skipValidationIfBaseFitRejected',true, ...
        'outputDir',fullfile(root,'output_matlab', ...
            'full_stack_ism_wavefront_air_diagnostic')};

    args=overrideNameValues(args,varargin);
    result=estimateFullStackISMWavefront(alignmentCsv,args{:});

    fprintf(['\nDiagnostic only: inspect full_stack_fit_summary.png, ' ...
        'selected_plane_detector_hex_fit.png, and ' ...
        'selected_plane_spatial_fit.png. Detailed three-plane pages are in ' ...
        'selected_plane_fit_pages. Do not command the DM from this fit.\n\n']);
end

function args=overrideNameValues(defaults,userArgs)
    args=defaults;
    for k=1:2:numel(userArgs)
        name=userArgs{k};
        found=false;
        for q=1:2:numel(args)
            if strcmpi(args{q},name)
                args{q+1}=userArgs{k+1};
                found=true;
                break;
            end
        end
        if ~found
            args=[args userArgs(k:k+1)]; %#ok<AGROW>
        end
    end
end
